import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Fused LogSumExp + ReLU CUDA kernel
logsumexp_relu_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void logsumexp_relu_kernel(const float* input, float* output,
                                     int batch_size, int channels,
                                     int depth, int height, int width) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int spatial_size = depth * height * width;
    const int total_elements = batch_size * spatial_size;

    if (idx >= total_elements) return;

    const int batch = idx / spatial_size;
    const int spatial_idx = idx % spatial_size;
    const int d = spatial_idx / (height * width);
    const int h = (spatial_idx / width) % height;
    const int w = spatial_idx % width;

    float max_val = -INFINITY;
    for (int c = 0; c < channels; ++c) {
        const int input_idx = ((batch * channels + c) * depth + d) * height * width + h * width + w;
        max_val = fmaxf(max_val, input[input_idx]);
    }

    float sum_exp = 0.0f;
    for (int c = 0; c < channels; ++c) {
        const int input_idx = ((batch * channels + c) * depth + d) * height * width + h * width + w;
        sum_exp += expf(input[input_idx] - max_val);
    }

    const float log_sum_exp = logf(sum_exp) + max_val;
    const int output_idx = ((batch * 1 + 0) * depth + d) * height * width + h * width + w;
    output[output_idx] = fmaxf(0.0f, log_sum_exp);
}

torch::Tensor logsumexp_relu_cuda(torch::Tensor input) {
    input = input.contiguous();
    const auto sizes = input.sizes();
    const int batch_size = sizes[0];
    const int channels = sizes[1];
    const int depth = sizes[2];
    const int height = sizes[3];
    const int width = sizes[4];

    auto output = torch::zeros({batch_size, 1, depth, height, width}, input.options());

    const int total_elements = batch_size * depth * height * width;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    logsumexp_relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        depth,
        height,
        width
    );

    return output;
}
"""

logsumexp_relu_cpp = "torch::Tensor logsumexp_relu_cuda(torch::Tensor input);"

logsumexp_relu = load_inline(
    name="logsumexp_relu",
    cpp_sources=logsumexp_relu_cpp,
    cuda_sources=logsumexp_relu_source,
    functions=["logsumexp_relu_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)
        self.max_pool = nn.MaxPool3d(kernel_size=2, stride=2)
        self.logsumexp_relu = logsumexp_relu

    def forward(self, x):
        x = self.conv(x)
        x = self.max_pool(x)
        x = self.logsumexp_relu.logsumexp_relu_cuda(x)
        return x
